package dev.deltavisuals.util;

import net.fabricmc.loader.api.FabricLoader;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.Clip;
import javax.sound.sampled.LineEvent;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Hit sounds generated by code (no audio files are shipped) plus loading of a user WAV/AIFF/AU file.
 * Playback uses javax.sound.sampled on a background thread, so it never stalls the render thread.
 */
public final class SoundBank {
    private static final Logger LOG = LoggerFactory.getLogger("DeltaVisuals/Sound");
    public static final int RATE = 44100;
    private static final double TAU = Math.PI * 2;
    private static final int MAX_CUSTOM_SECONDS = 5;

    /** Interleaved 16 bit PCM. */
    public static final class Pcm {
        public final short[] data; public final int channels; public final float rate;
        Pcm(short[] data, int channels, float rate) { this.data = data; this.channels = channels; this.rate = rate; }
    }

    private static final ExecutorService EXEC = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "DeltaVisuals-Audio");
        t.setDaemon(true);
        return t;
    });
    private static final Pcm[] SYNTH = new Pcm[5];
    private static boolean failedLogged;

    private SoundBank() {}

    // ------------------------------------------------------------------ synthesized sounds

    /** 0 = bell (fallback for the vanilla bell), 1..4 = Hit Sound 1..4. */
    public static synchronized Pcm synth(int id) {
        if (id < 0 || id >= SYNTH.length) id = 1;
        if (SYNTH[id] == null) SYNTH[id] = build(id);
        return SYNTH[id];
    }

    private static Pcm build(int id) {
        double len = switch (id) { case 0 -> 1.1; case 1 -> 0.17; case 2 -> 0.34; case 3 -> 0.30; default -> 0.14; };
        int n = (int) (len * RATE);
        float[] f = new float[n];
        for (int i = 0; i < n; i++) {
            double t = i / (double) RATE, v;
            switch (id) {
                case 0 -> {      // bell: inharmonic partials with individual decay
                    double[] ratio = {1.0, 2.0, 2.76, 4.07, 5.4, 6.8}, amp = {1.0, 0.55, 0.45, 0.25, 0.16, 0.10}, dec = {3.2, 4.0, 5.0, 7.0, 9.0, 12.0};
                    v = 0;
                    for (int k = 0; k < ratio.length; k++) v += amp[k] * Math.sin(TAU * 784 * ratio[k] * t) * Math.exp(-dec[k] * t);
                    v *= 0.38;
                }
                case 1 -> {      // short pleasant pluck
                    v = Math.sin(TAU * 988 * t) * Math.exp(-t * 30) + 0.4 * Math.sin(TAU * 1976 * t) * Math.exp(-t * 48)
                        + 0.12 * Math.sin(TAU * 2960 * t) * Math.exp(-t * 80);
                    v *= Math.min(1.0, t / 0.002);
                }
                case 2 -> {      // ringing FM bell
                    double idx = 4.0 * Math.exp(-t * 18);
                    v = Math.sin(TAU * 1568 * t + idx * Math.sin(TAU * 1568 * 3.5 * t)) * Math.exp(-t * 13)
                        + 0.3 * Math.sin(TAU * 1568 * 2.76 * t) * Math.exp(-t * 20);
                    v *= Math.min(1.0, t / 0.0015);
                }
                case 3 -> {      // soft rounded tone
                    double att = Math.min(1.0, t / 0.012);
                    att = att * att * (3 - 2 * att);
                    v = (Math.sin(TAU * 392 * t) + 0.28 * Math.sin(TAU * 784 * t) + 0.08 * Math.sin(TAU * 1176 * t)) * Math.exp(-t * 14) * att;
                }
                default -> {     // high blip with a small upward chirp
                    double fr = 2349 * (1.0 + 0.08 * Math.min(1.0, t / 0.06));
                    v = Math.sin(TAU * fr * t) * Math.exp(-t * 36) + 0.3 * Math.sin(TAU * fr * 2 * t) * Math.exp(-t * 55);
                    v *= Math.min(1.0, t / 0.001);
                }
            }
            f[i] = (float) v;
        }
        float peak = 0.001f;
        for (float x : f) peak = Math.max(peak, Math.abs(x));
        short[] s = new short[n];
        float norm = 0.85f / peak;
        int fade = Math.min(n, 220);
        for (int i = 0; i < n; i++) {
            float g = i >= n - fade ? (n - i) / (float) fade : 1f;     // tiny fade-out so the tail never clicks
            s[i] = (short) Math.round(f[i] * norm * g * 32767f);
        }
        return new Pcm(s, 1, RATE);
    }

    // ------------------------------------------------------------------ custom file

    public static Path soundsDir() { return FabricLoader.getInstance().getConfigDir().resolve("delta_visuals").resolve("sounds"); }

    /** First existing custom file: custom.wav, custom.aiff, custom.aif, custom.au. */
    public static Path customFile() {
        for (String n : new String[]{"custom.wav", "custom.aiff", "custom.aif", "custom.au"}) {
            Path p = soundsDir().resolve(n);
            if (Files.isRegularFile(p)) return p;
        }
        return null;
    }

    public static void createSoundsDir() {
        try { Files.createDirectories(soundsDir()); } catch (Exception e) { LOG.warn("Cannot create sounds folder", e); }
    }

    /** Loads the custom file. Returns null (and a message in lastError[0]) when it is missing or unreadable. */
    public static Pcm loadCustom(String[] lastError) {
        Path p = customFile();
        if (p == null) { lastError[0] = "custom.wav not found"; return null; }
        File file = p.toFile();
        try (AudioInputStream raw = AudioSystem.getAudioInputStream(file)) {
            AudioFormat src = raw.getFormat();
            int ch = Math.max(1, Math.min(2, src.getChannels()));
            AudioFormat pcm = new AudioFormat(AudioFormat.Encoding.PCM_SIGNED, src.getSampleRate(), 16, ch, ch * 2, src.getSampleRate(), false);
            try (AudioInputStream in = AudioSystem.getAudioInputStream(pcm, raw)) {
                int maxBytes = (int) (src.getSampleRate() * MAX_CUSTOM_SECONDS) * ch * 2;
                ByteArrayOutputStream out = new ByteArrayOutputStream();
                byte[] buf = new byte[8192];
                int r;
                while ((r = in.read(buf)) > 0 && out.size() < maxBytes) out.write(buf, 0, r);
                byte[] b = out.toByteArray();
                int frames = b.length / (ch * 2);
                short[] s = new short[frames * ch];
                for (int i = 0; i < s.length; i++) s[i] = (short) ((b[i * 2] & 255) | (b[i * 2 + 1] << 8));
                if (s.length == 0) { lastError[0] = "file is empty"; return null; }
                lastError[0] = null;
                return new Pcm(s, ch, src.getSampleRate());
            }
        } catch (Exception e) {
            lastError[0] = "unsupported file (use PCM WAV)";
            LOG.warn("Cannot read custom hit sound {}", p, e);
            return null;
        }
    }

    // ------------------------------------------------------------------ playback

    /** volume 0..1.5 (squared curve), pitch 0.5..2 (resampled, changes length like a real pitch shift). */
    public static void play(Pcm pcm, float volume, float pitch) {
        if (pcm == null || volume <= 0.001f) return;
        final float vol = volume * volume, step = Math.max(0.25f, Math.min(4f, pitch));
        EXEC.execute(() -> {
            try {
                int ch = pcm.channels;
                int frames = pcm.data.length / ch;
                int outFrames = Math.max(1, (int) (frames / step));
                byte[] out = new byte[outFrames * ch * 2];
                for (int i = 0; i < outFrames; i++) {
                    float pos = i * step;
                    int i0 = Math.min(frames - 1, (int) pos), i1 = Math.min(frames - 1, i0 + 1);
                    float fr = pos - i0;
                    for (int c = 0; c < ch; c++) {
                        float a = pcm.data[i0 * ch + c], b = pcm.data[i1 * ch + c];
                        int v = Math.round((a + (b - a) * fr) * vol);
                        v = Math.max(-32768, Math.min(32767, v));
                        int o = (i * ch + c) * 2;
                        out[o] = (byte) v; out[o + 1] = (byte) (v >> 8);
                    }
                }
                AudioFormat fmt = new AudioFormat(pcm.rate, 16, ch, true, false);
                Clip clip = AudioSystem.getClip();
                clip.addLineListener(e -> { if (e.getType() == LineEvent.Type.STOP) clip.close(); });
                clip.open(fmt, out, 0, out.length);
                clip.start();
            } catch (Throwable t) {
                if (!failedLogged) { failedLogged = true; LOG.warn("Hit sound playback failed (no audio line?)", t); }
            }
        });
    }
}
